//! Properties of sources generated by Qt tools.

use rcmake_base::{BString, ByteSlice};
use rcmake_model::{BT, ProjectModel, Target};

use super::{ResolveError, TargetPlan, missing_origin};

#[derive(Clone, Copy)]
pub(super) enum GeneratedSource {
    MocCompilation,
    MocModule,
    Resource,
    Auxiliary,
}

pub(super) fn add_source(
    model: &mut ProjectModel,
    plan: &TargetPlan,
    origin: &Target,
    file: BString,
    kind: GeneratedSource,
) -> Result<(), ResolveError> {
    mark_configured(model, plan, origin, &file, kind);
    let sources = &mut model
        .target_mut(plan.id)
        .ok_or_else(missing_origin)?
        .sources;
    let source = BT::new(file, origin.backtrace.clone());
    if matches!(kind, GeneratedSource::MocCompilation) {
        sources.insert(0, source);
    } else {
        sources.push(source);
    }
    Ok(())
}

pub(super) fn mark_configured(
    model: &mut ProjectModel,
    plan: &TargetPlan,
    origin: &Target,
    pattern: &BString,
    kind: GeneratedSource,
) {
    if pattern.starts_with(b"$<$<CONFIG:") {
        return;
    }
    if pattern.windows(9).any(|window| window == b"$<CONFIG>") {
        for config in &plan.configs {
            let file = BString::from(pattern.replace(b"$<CONFIG>", config.0.as_slice()));
            mark_source(model, origin, file, kind);
        }
    } else {
        mark_source(model, origin, pattern.clone(), kind);
    }
}

pub(super) fn mark_source(
    model: &mut ProjectModel,
    origin: &Target,
    path: BString,
    kind: GeneratedSource,
) {
    model.mark_generated(origin.dir, path.clone());
    let props = model
        .dir_mut(origin.dir)
        .source_props
        .entry(path)
        .or_default();
    props.set("SKIP_AUTOGEN".into(), "ON".into());
    props.set("SKIP_LINTING".into(), "ON".into());
    match kind {
        GeneratedSource::MocCompilation => {}
        GeneratedSource::MocModule => {
            props.set("CXX_SCAN_FOR_MODULES".into(), "1".into());
            props.set("SKIP_PRECOMPILE_HEADERS".into(), "ON".into());
        }
        GeneratedSource::Resource => {
            props.set("CXX_SCAN_FOR_MODULES".into(), "0".into());
            props.set("SKIP_UNITY_BUILD_INCLUSION".into(), "ON".into());
        }
        GeneratedSource::Auxiliary => {
            props.set("CXX_SCAN_FOR_MODULES".into(), "0".into());
        }
    }
}
